document.addEventListener('DOMContentLoaded', function () {
  let o = new WebSocket('wss://' + window.location.host + '/ws/user/');
  ((o.onopen = function () {
    console.log('Connected');
  }),
    (o.onmessage = function () {
      console.log('Messaged');
    }),
    (o.onclose = function () {
      console.log('Closed');
    }),
    (o.onerror = function () {
      console.log('Error!');
    }));
});
